-- DO NOT EDIT THIS FILE. MAKE YOUR CHANGES IN CUSTOM.D.

hl.window_rule({
    name = "suppress-maximize-events",
    match = { class = ".*" },
    suppress_event = "maximize",
})

hl.window_rule({
    name = "fix-xwayland-drags",
    match = {
        class = "^$",
        title = "^$",
        xwayland = true,
        float = true,
        fullscreen = false,
        pin = false,
    },
    no_focus = true,
})

hl.layer_rule({
    name = "walker-blur",
    match = { namespace = "walker" },
    blur = true,
    ignore_alpha = 0.41,
})

hl.layer_rule({
    name = "shell-bar-blur",
    match = { namespace = "hyprland-shell:bar" },
    blur = true,
    blur_popups = true,
    ignore_alpha = 0.41,
})

hl.layer_rule({
    name = "shell-notifs-blur",
    match = { namespace = "hyprland-shell:notifs" },
    blur = true,
    ignore_alpha = 0.41,
    no_anim = true,
})

if not HLDE.env_set("HLDE_NO_TRANSPARENT") then
    hl.window_rule({
        name = "transparent-non-fullscreen",
        match = { fullscreen = false },
        opacity = "0.95",
    })

    hl.window_rule({
        name = "transparent-dolphin",
        match = { class = "org\\.kde\\.dolphin" },
        opacity = "0.95",
    })

    hl.window_rule({
        name = "opaque-kitty",
        match = { class = "kitty" },
        opacity = "1",
    })
end

hl.window_rule({
    name = "float-share-picker",
    match = { class = "hyprland-share-picker" },
    float = true,
})
